"use client"

import { useState, useMemo } from "react"
import { Check, Copy } from "lucide-react"
import { highlightSync } from "@/lib/syntax-highlight"
import { useCopyToClipboard } from "@/hooks/use-copy-to-clipboard"

interface CommandBlockProps {
  command: string
  // If true, it will parse the command and provide tabs for npm, yarn, pnpm, bun
  isPackageManager?: boolean
}

const packageManagers = ["npm", "yarn", "pnpm", "bun"]

function getCommandForPackageManager(baseCommand: string, pm: string) {
  // Normalize to a base package list
  let packages = ""
  let isInstall = false
  let isExecute = false
  let executeCmd = ""

  if (baseCommand.match(/(npm install|npm i|yarn add|pnpm add|bun add)\s+(.+)/)) {
    isInstall = true
    packages = baseCommand.replace(/^(npm install|npm i|yarn add|pnpm add|bun add)\s+/, "").trim()
  } else if (baseCommand.match(/(npx|yarn dlx|pnpm dlx|bunx)\s+(.+)/)) {
    isExecute = true
    executeCmd = baseCommand.replace(/^(npx|yarn dlx|pnpm dlx|bunx)\s+/, "").trim()
  }

  if (isInstall) {
    if (pm === "npm") return `npm install ${packages}`
    if (pm === "yarn") return `yarn add ${packages}`
    if (pm === "pnpm") return `pnpm add ${packages}`
    if (pm === "bun") return `bun add ${packages}`
  }
  
  if (isExecute) {
    if (pm === "npm") return `npx ${executeCmd}`
    if (pm === "yarn") return `yarn dlx ${executeCmd}`
    if (pm === "pnpm") return `pnpm dlx ${executeCmd}`
    if (pm === "bun") return `bunx ${executeCmd}`
  }

  // Fallback
  return baseCommand
}

export function CommandBlock({ command, isPackageManager = true }: CommandBlockProps) {
  const { copied, copy } = useCopyToClipboard()
  const [activeTab, setActiveTab] = useState(0)

  const isNpmCommand = isPackageManager && (command.includes("npm ") || command.includes("npx ") || command.includes("yarn ") || command.includes("pnpm ") || command.includes("bun "))
  const tabs = isNpmCommand ? packageManagers : []
  
  const currentCommand = isNpmCommand 
    ? getCommandForPackageManager(command, packageManagers[activeTab])
    : command

  const highlightedHtml = useMemo(() => {
    return highlightSync(currentCommand, "bash")
  }, [currentCommand])

  const handleCopy = () => copy(currentCommand.trim())

  return (
    <div className="code-block my-6" role="region" aria-label="Terminal command">
      {tabs.length > 0 && (
        <div className="code-block-header">
          <div className="flex items-center gap-4" role="tablist">
            {tabs.map((tab, index) => (
              <button
                key={tab}
                onClick={() => setActiveTab(index)}
                role="tab"
                aria-selected={activeTab === index}
                className={`code-block-tab min-h-[44px] min-w-[44px] relative ${activeTab === index ? "active" : ""}`}
              >
                {tab}
                {activeTab === index && <div className="absolute bottom-0 left-0 right-0 h-0.5 bg-indigo-500" />}
              </button>
            ))}
          </div>
          <div className="flex items-center gap-1">
            <button
              onClick={handleCopy}
              className={`code-block-icon-btn min-h-[44px] min-w-[44px] p-2 ${copied ? "text-green-500" : ""}`}
              aria-label={copied ? "Command copied" : "Copy command"}
            >
              {copied ? <Check className="h-4 w-4" /> : <Copy className="h-4 w-4" />}
            </button>
          </div>
        </div>
      )}

      <div className="relative group">
        <div
          className="code-block-content mt-0!"
          dangerouslySetInnerHTML={{ __html: highlightedHtml }}
        />
        {tabs.length === 0 && (
          <button
            onClick={handleCopy}
            className={`absolute right-3 top-3 p-2 rounded-md bg-zinc-800/50 hover:bg-zinc-700 transition-colors ${copied ? "text-green-500" : "text-zinc-400 hover:text-zinc-200"}`}
            aria-label={copied ? "Command copied" : "Copy command"}
          >
            {copied ? <Check className="h-4 w-4" /> : <Copy className="h-4 w-4" />}
          </button>
        )}
      </div>
    </div>
  )
}
